<?php
declare(strict_types=1);
namespace InvoiceDesk;
final class InvoiceView {
    public static function html(array $row): string {
        $p=json_decode($row['payload'],true);$i=$p['invoice'];$c=$i['_snapshot']??$p['client'];$s=(new Service())->settings();$items='';
        foreach(rows($i['items']??[],'item') as $item)$items.='<tr><td>'.nl2br(h($item['description']??'')).'</td><td>'.h($item['taxed']?'Yes':'No').'</td><td class="num">'.h($item['amount']).'</td></tr>';
        $address=implode(', ',array_filter([$c['address1']??'',$c['address2']??'',$c['city']??'',$c['state']??'',$c['postcode']??'',$c['country']??'']));
        return '<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Invoice '.h($row['number']).'</title><style>body{font:15px system-ui;color:#18181b;max-width:900px;margin:40px auto;padding:24px}h1{font-size:34px;margin:16px 0}.muted{color:#61616b}.head{display:flex;justify-content:space-between;gap:24px}table{width:100%;border-collapse:collapse;margin-top:30px}td,th{padding:14px;text-align:left;border-bottom:1px solid #ddd;vertical-align:top}.num{text-align:right}aside{background:#f4f1ff;padding:16px;border-radius:10px;margin:24px 0}pre{white-space:pre-wrap;font:inherit}@media print{body{margin:0;padding:0}button{display:none}}</style><body><button onclick="window.print()">Print / Save as PDF</button><p class="muted">Munshi Ji · Administrative copy from cached WHMCS data</p><div class="head"><div><h1>'.h($s['company']).'</h1><p>Supplier GSTIN: '.h($s['supplier_gstin']?:'Not configured').'</p></div><div><h1>Invoice '.h($row['number']).'</h1><p>'.h($row['status']).' · '.h($row['currency']).'</p></div></div><div class="head"><div><strong>Billed to</strong><p>'.h($row['client_name']).'<br>'.h($address).'<br>Recipient GSTIN: '.h($row['gstin']?:'Not found').'</p></div><div><p>Issued: '.h($row['date']).'<br>Due: '.h($row['due_date']).'<br>Paid: '.h($row['paid_date']??'—').'</p></div></div><aside>GSTIN check: '.h($row['gst_status']).' · Evidence: '.h($row['basis']).'. Registration status has not been verified. Use the original WHMCS PDF for the issued document.</aside><table><thead><tr><th>Description</th><th>Taxed</th><th class="num">Amount</th></tr></thead><tbody>'.$items.'</tbody></table><table><tbody><tr><td>Subtotal</td><td class="num">'.h(Money::decimal($row['subtotal'])).'</td></tr><tr><td>Tax level 1 / level 2</td><td class="num">'.h(Money::decimal($row['tax'])).' / '.h(Money::decimal($row['tax2'])).'</td></tr><tr><td><strong>Total</strong></td><td class="num"><strong>'.h($row['currency']).' '.h(Money::decimal($row['total'])).'</strong></td></tr><tr><td>Credit applied / Balance</td><td class="num">'.h(Money::decimal($row['credit'])).' / '.h(Money::decimal($row['balance'])).'</td></tr></tbody></table><pre>'.h($i['notes']??'').'</pre><p class="muted">Data fetched '.h($row['fetched_at']).'. Original invoice ID #'.h($row['id']).'. This copy does not replace the original tax invoice.</p></body></html>';
    }
}
